// jakarta.servlet.Filter definiuje:
// 1) init(FilterConfig config) - wywolywane RAZ, przy starcie filtru
// 2) doFilter(req, resp, chain) - serce filtru, dla KAZDEGO zadania
// 3) destroy() - wywolywane RAZ, przy zamykaniu filtru

class TimingFilter implements Filter {
    public void init(FilterConfig filterConfig) {
        System.out.println("init() - filtr wystartowal");
    }
    public void doFilter(ServletRequest request, ServletResponse response, FilterChain chain)
            throws IOException, ServletException {
        long start = System.currentTimeMillis();
        chain.doFilter(request, response); // KLUCZOWE - przekazuje dalej
        long elapsed = System.currentTimeMillis() - start;
        System.out.println("czas: " + elapsed + " ms");
    }
    public void destroy() { System.out.println("destroy()"); }
}

// Tak jak serwlety rejestrowalismy przez Tomcat.addServlet(...), tak
// filtry rejestrujemy przez dwie klasy z pakietu
// org.apache.tomcat.util.descriptor.web:
// - FilterDef - definicja filtru: nazwa + instancja filtru
// - FilterMap - mapowanie: ktora nazwa filtru na jaki wzorzec URL

FilterDef filterDef = new FilterDef();
filterDef.setFilterName("timingFilter");
filterDef.setFilter(new TimingFilter());
context.addFilterDef(filterDef);

FilterMap filterMap = new FilterMap();
filterMap.setFilterName("timingFilter");
filterMap.addURLPattern("/*"); // filtr dziala dla WSZYSTKICH adresow
context.addFilterMap(filterMap);
